'use strict';
const $=s=>document.querySelector(s),E=HeidiExplorer,esc=E.esc;
const KEY='heidi-cases-v3';let persisted={};try{const current=localStorage.getItem(KEY);persisted=JSON.parse(current||localStorage.getItem('heidi-exploration-v2')||'{}');if(!current)persisted.drafts={}}catch{}
const state={notes:Array.isArray(persisted.notes)?persisted.notes:[],drafts:persisted.drafts||{},marks:Array.isArray(persisted.marks)?persisted.marks:[],pair:[],query:'',kind:'Alle',until:2025,videoOnly:false,order:E.segments.map(s=>s.id),duration:5,muted:false,image:'buch-alp',pending:null,yearIndex:0};
const eras=[{year:1880,title:'Ein Kind wechselt die Welt.',image:'buch',text:'1880 und 1881 erscheinen Spyris zwei Heidi-Romane. Lesen, Heimweh und Fürsorge verbinden Alp und Stadt.',refs:['klimek','dossier'],ids:['1920','1937']},{year:1937,title:'Heidi wird ein Star.',image:'1937',text:'Hollywood trifft auf den Schweizer Stoff. Shirley Temples Starpersona wird Teil der Erzählung.',refs:['afi','leskau'],ids:['1937','1952']},{year:1952,title:'Wie sieht Heimat aus?',image:'1952',text:'Die Schweizer Filme machen die Alpen zum Kinoraum. 1955 tritt die Farbe hinzu.',refs:['filmo','tomkowiak','srf55'],ids:['1952','1955']},{year:1968,title:'Das Fernsehen bestimmt den Takt.',image:'1968',text:'Ein Stoff wandert zwischen Kinofilm, Fernsehspiel und Serie. Sendeformat und Erzählzeit gehören zusammen.',refs:['lib68','srf78'],ids:['1968','1978']},{year:1974,title:'Ein ganzes Jahr mit Heidi.',image:'1974',text:'Takahatas Serie gibt alltäglichen Handlungen Zeit. Übersetzung und Synchronisation tragen sie in andere Lebenswelten.',refs:['takahata','bando'],ids:['1974','2015cgi']},{year:2001,title:'Die Gegenwart zieht ein.',image:'2001',text:'Imbodens Heidi lebt mit E-Mail und Grossstadtalltag. Die Modernisierung verändert auch Beziehungen und Möglichkeiten.',refs:['porta','swissinfo'],ids:['2001','2007teen']},{year:2015,title:'Zurück ins Gestern. Mit Zukunft?',image:'2015',text:'Der historische Realfilm und die CGI-Serie entstehen im selben Jahr. Welche Vorstellungen von Kindheit treffen sich hier?',refs:['gsponer','cgi'],ids:['2015','2015cgi']},{year:2023,title:'Eine Ikone gerät aus der Form.',image:'2022',text:'Mad Heidi und Karpis KI-Trailer verschieben Genre und Bildsprache. Der Trailer von 2023 ist ein eigenständiges Experiment.',refs:['mad','karpi'],ids:['2022','2023karpi']},{year:2025,title:'Neue Abenteuer, neue Konflikte.',image:'2025',text:'Die Legende vom Luchs setzt Heidi in eine neue Handlung um Natur und wirtschaftliche Interessen.',refs:['lynx'],ids:['2025','2015']}];
function persist(){try{localStorage.setItem(KEY,JSON.stringify({notes:state.notes,drafts:state.drafts,marks:state.marks}));return true}catch{toast('Speichern im Browser nicht möglich. Bitte dein Entdeckungsbuch herunterladen.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function imageFor(id){return images.find(i=>i.id===id&&i.path)}
function photo(id,cls='',extra=''){const i=imageFor(id);return i?`<img class="${cls}" src="${esc(i.path)}" alt="${esc(i.caption)}" ${extra}>`:''}
function credit(id){const i=imageFor(id);return i?`<a class="image-credit" href="${esc(i.source)}" target="_blank" rel="noopener">${esc(i.caption)} · Bildnachweis ↗</a>`:''}
function refs(keys){return keys.filter(k=>sources[k]).map(k=>`<a class="source-link" href="${esc(sources[k].url)}" target="_blank" rel="noopener">${esc(sources[k].name)} ↗</a>`).join('')}
function art(f){return imageFor(f.id)?photo(f.id,'film-art','loading="lazy"'):`<div class="typographic-art tone-${parseInt(f.year)%4}" aria-hidden="true"><small>${esc(f.kind)}</small><b>${esc(f.year)}</b><span>${esc(f.title.replace('Heidi','').replace('·','')||'HEIDI')}</span></div>`}
function card(f){return `<article class="film-card"><button class="film-open" data-film="${f.id}" aria-label="${esc(f.title+' '+f.year+' ansehen')}">${art(f)}<span class="film-hover">${f.clip||f.video?'▶ Entdecken':'↗ Archiv öffnen'}</span></button><div class="card-meta"><span>${esc(f.year)}</span><button class="pair-add ${state.pair.includes(f.id)?'selected':''}" data-pair="${f.id}" aria-pressed="${state.pair.includes(f.id)}" aria-label="${esc(f.title+' '+f.year+' zum Vergleich auswählen')}">${state.pair.includes(f.id)?'✓':'＋'}</button></div><button class="film-title" data-film="${f.id}">${esc(f.title)}</button><small>${esc(f.kind)}${f.fullVideo?' · Ganzer Film':f.clip?' · Video':f.video?' · Fragment':' · Clip offen'}</small></article>`}
function roomHeading(kicker,title,sub){return `<div class="room-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1></div><p>${sub}</p></div>`}
function home(){return `<section class="landing"><div class="hero-scene">${photo('hero','','fetchpriority="high"')}<div class="hero-shade"></div><div class="hero-copy"><p class="eyebrow">EINE GESCHICHTE, DIE NICHT STILLSTEHT</p><h1>Welche Heidi<br>entdeckst du?</h1><p>Peters Tat untersuchen. Buch und Stadt neu montieren. Plakate entschlüsseln.</p><a class="solid light" href="#kino">In die Filmwelt eintauchen <span>↗</span></a></div><div class="floating-still">${photo('2015')}<span>Ein Kind. Unzählige Blickwinkel.</span></div><div class="hero-bottom"><span>1880 — HEUTE</span>${credit('hero')}</div></div><div class="portals"><a href="#kino"><span>01 / ANSEHEN</span><h2>35-mal Heidi.</h2><p>Von frühem Farbfilm bis zum KI-Experiment.</p><b>Filmwelt ↗</b></a><a href="#labor"><span>02 / VERÄNDERN</span><h2>Dein Schnitt.<br>Deine Geschichte.</h2><p>Vier echte Ausschnitte. Eine andere Wirkung.</p><b>Schnittlabor ↗</b></a><a href="#spuren"><span>03 / AUFSPÜREN</span><h2>Wer lenkt<br>deinen Blick?</h2><p>Hände, Schriftgrössen und Gegenstände: acht Bilder, acht eigene Fragen.</p><b>Bildspuren ↗</b></a><a href="#zeit"><span>04 / ZEITREISEN</span><h2>Jede Zeit<br>erfindet Heidi.</h2><p>Bewege dich durch ihre Verwandlungen.</p><b>Zeitreise ↗</b></a></div></section>`}
function cinema(){return `<section class="room cinema-room">${roomHeading('01 / DIE FILMWELT','Eine Figur.<em>Viele Welten.</em>','Öffne einen Film. Oder wähle mit ＋ zwei Fassungen und schau sie nebeneinander an.')}<div class="cinema-tools"><label class="search"><span aria-hidden="true">⌕</span><input id="film-search" type="search" placeholder="Ein Jahr, ein Land, eine Heidi …" aria-label="Filmarchiv durchsuchen" value="${esc(state.query)}"></label><label class="year-filter">Bis <output id="year-output">${state.until}</output><input id="year-limit" aria-label="Filme bis zum Jahr" type="range" min="1920" max="2025" value="${state.until}"></label><label class="video-only"><input id="video-only" type="checkbox" ${state.videoOnly?'checked':''}> Mit Video</label></div><div class="filter-row"><div class="filters">${['Alle','Kino','Fernsehen','Animation','Neudeutung','Kurzfilm','Kunstfilm'].map(k=>`<button data-kind="${k}" class="${state.kind===k?'active':''}" aria-pressed="${state.kind===k}">${k}</button>`).join('')}</div><span id="film-count" role="status"></span><button class="text-button" data-action="surprise">Zufallsfund ↗</button></div><div id="film-grid" class="film-grid"></div><div class="archive-footer"><button data-action="coverage">31 / 35 Einträge mit Video · offene Funde ansehen</button><button data-action="registers">Schnittfassungen & weitere Archivspuren ↗</button></div></section>`}
function renderFilms(){const list=E.filterFilms(films,state);$('#film-grid').innerHTML=list.map(card).join('')||`<div class="empty"><h2>Hier ist es gerade still.</h2><p>Für diese Kombination gibt es keinen Treffer.</p><button class="solid" data-action="reset-filters">Alle Filme wieder zeigen</button></div>`;$('#film-count').textContent=`${list.length} Entdeckungen`}
function caseForPair(){return Object.values(HeidiCases).find(c=>c.pair&&c.pair.every(id=>state.pair.includes(id)))}
function draftKey(key){return HeidiCases[key]?.revision?key+'@'+HeidiCases[key].revision:key}
function materialFigures(c){const ids=c.materialImages||(c.materialImage?[c.materialImage]:[]);return ids.length?`<div class="case-figures">${ids.map(id=>`<figure><a href="${esc(imageFor(id).path)}" target="_blank" rel="noopener" aria-label="${esc(imageFor(id).caption+' vergrössern')}">${photo(id)}</a><figcaption>${credit(id)}</figcaption></figure>`).join('')}</div>`:''}
function taskPanel(key){const c=HeidiCases[key];if(!c)throw new Error('Individuelle Aufgabe fehlt: '+key);return `<section class="case-task" data-case="${key}"><p class="eyebrow">${c.image||c.materialImage||c.materialImages?'AM BILD':c.seek?'AM FRAGMENT':key==='montage'?'SCHNITTEXPERIMENT':'EINZELUNTERSUCHUNG'}</p><h3>${esc(c.title)}</h3><p class="case-location">${esc(c.where)}</p>${c.seek?`<div class="case-seeks">${c.seek.map(([label,time])=>`<button class="solid" data-seek="${time}">▶ ${Math.floor(time/60)}:${String(time%60).padStart(2,'0')} · ${esc(label)}</button>`).join('')}</div>`:''}<details class="case-material" ${c.seek||c.image||key==='montage'?'':'open'}><summary>Material für diese Frage</summary><p>${esc(c.material)}</p>${refs(c.refs)}</details>${materialFigures(c)}<p class="case-action">${esc(c.action)}</p><p class="case-question">${esc(c.question)}</p>${observer(key)}<details class="reveal"><summary>Begründete Einordnung zu dieser Frage</summary><p>${esc(c.answer)}</p>${refs(c.refs)}</details></section>`}
function observer(key){return `<div class="observer"><label for="draft-${key}">Deine Antwort auf diese Frage</label><textarea id="draft-${key}" data-draft="${key}">${esc(state.drafts[draftKey(key)]||'')}</textarea><div class="observer-actions"><button class="solid" data-save="${key}">Antwort festhalten ＋</button><button class="text-button" data-reflect="${key}">Rückmeldung zu dieser Frage ↗</button></div><div id="reflection-${key}" class="reflection" aria-live="polite"></div></div>`}
function freeNotebook(key){return `<div class="observer"><label for="draft-${key}">Freies Vergleichsnotizbuch · keine vorgegebene Aufgabe</label><textarea id="draft-${key}" data-draft="${key}">${esc(state.drafts[draftKey(key)]||'')}</textarea><button class="solid" data-save="${key}">Notiz speichern ＋</button></div>`}
function closeOverlay(){stopMontage();$('#overlay').close();$('#overlay-body').innerHTML=''}
function overlay(title,html,cls=''){const d=$('#overlay');d.className=cls;$('#overlay-body').innerHTML=`<div class="dialog-top"><h2 id="overlay-title">${esc(title)}</h2><button data-action="close" class="close" aria-label="Ansicht schliessen">×</button></div>${html}`;if(!d.open)d.showModal();d.scrollTop=0}
function player(f,suffix='main',full=false){const v=full?f.fullVideo?.url:f.video,c=f.clip;const id='player-'+suffix+'-'+f.id;if(v)return `<div class="player-shell"><video controls playsinline preload="none" ${imageFor(f.id)?`poster="${imageFor(f.id).path}"`:''} aria-label="${esc(f.title+' '+f.year+(full?' vollständiger Film':' Fragment'))}"><source src="${esc(v)}" type="video/mp4"></video></div><p class="media-meta">${full?esc(f.fullVideo.label):'Bereitgestelltes Fragment · 2:30'} · <a href="${esc(v)}" target="_blank" rel="noopener">Separat öffnen ↗</a></p>`;if(c)return `<div class="player-shell" id="${id}"><button class="play-launch" data-play="${f.id}" data-target="${id}">${photo(f.id)}<span class="play-disc">▶</span><strong>${esc(c.label)}</strong><small>${esc(c.language)} · ${esc(c.author)}</small></button></div><p class="media-meta">${esc(c.provider==='mp4'?'Traileranbieter':c.provider)} · <a href="${esc(c.url)}" target="_blank" rel="noopener">Video separat öffnen ↗</a></p>`;return `<div class="no-video"><span>ARCHIVSPUR</span><h3>Das Bild bleibt noch offen.</h3><p>${esc(f.clipGap||'Noch kein geprüfter Ausschnitt verfügbar.')}</p>${refs(f.refs)}</div>`}
function loadClip(id,target){const f=films.find(f=>f.id===id),c=f?.clip,node=document.getElementById(target);if(!c||!node)return;node.innerHTML=c.provider==='mp4'?`<video controls playsinline preload="metadata" aria-label="${esc(f.title)}"><source src="${esc(c.embed)}" type="video/mp4"></video>`:`<iframe src="${esc(E.embedUrl(c))}" title="${esc(f.title+' '+f.year+' · '+c.label)}" allow="fullscreen; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`}
function openFilm(id,full=false){const f=films.find(f=>f.id===id);if(!f)return;const c=HeidiCases['film-'+id];overlay(f.title,`<div class="film-theatre"><div class="screen-column"><div class="eyebrow">${esc(f.year)} / ${esc(f.kind)} / ${esc(f.director)}</div>${player(f,'film',full)}${f.fullVideo?`<button class="text-button" data-film="${id}" data-full="${!full}">${full?'Zum offiziellen Szenenclip':'Vollständigen Realfilm ansehen · 1:50:50'} ↗</button>`:''}${f.clip?`<details class="quiet"><summary>Über diesen Ausschnitt</summary><p>${esc(f.clip.note)}</p></details>`:''}${credit(f.id)}<details class="reveal"><summary>Filmangaben & Quellen</summary><p>${esc(f.facts)}</p><p>${esc(f.country)}</p>${refs(f.refs)}${additionalImageSources[id]?`<a class="source-link" href="${esc(additionalImageSources[id].source)}" target="_blank" rel="noopener">${esc(additionalImageSources[id].caption)} ↗</a>`:''}</details>${c?.history?`<details class="reveal"><summary>${id==='1920'?'Prizma II und die überlieferte Datei':'Historischer Zusammenhang'}</summary><p>${esc(c.history)}</p>${refs(c.refs)}</details>`:''}<button class="text-button" data-pair="${id}">＋ Zum Vergleich ${state.pair.includes(id)?'(bereits ausgewählt)':''}</button>${Object.values(HeidiCases).filter(t=>t.pair?.includes(id)).map(t=>`<p><button class="text-button" data-case-pair="${t.id}">${esc(t.title)} · Vergleich öffnen ↗</button></p>`).join('')}</div><aside class="film-side">${c?taskPanel('film-'+id):`<section class="archive-only" data-archive="${id}"><p class="eyebrow">ARCHIVZUGANG</p><h3>Materialstand zu ${esc(f.title)}</h3><p>${esc(HeidiArchiveNotes[id])}</p>${refs(f.refs)}</section>`}</aside></div>`,'theatre-dialog')}
function dock(){const selected=state.pair.map(id=>films.find(f=>f.id===id)).filter(Boolean);$('#compare-dock').innerHTML=selected.length?`<div class="dock-inner"><div><small>DEIN DOPPELBLICK</small><span>${selected.map(f=>esc(f.year+' · '+f.title)).join(' + ')}</span></div><button class="solid light" data-action="compare" ${selected.length<2?'disabled':''}>${selected.length<2?'Noch eine Fassung wählen':'Nebeneinander ansehen ↗'}</button><button data-action="clear-pair" aria-label="Vergleichsauswahl leeren">×</button></div>`:'';$('#note-count').textContent=state.notes.length}
function compare(){if(state.pair.length!==2)return;const pair=state.pair.map(id=>films.find(f=>f.id===id)),c=caseForPair(),freeKey='frei-'+[...state.pair].sort().join('-');overlay(c?c.title:'Freier Filmvergleich',`<div class="dual-screens">${pair.map((f,i)=>`<div><p class="eyebrow">${i?'B':'A'} / ${esc(f.year)}</p><h3>${esc(f.title)}</h3>${player(f,'compare'+i)}<details class="quiet"><summary>Belegte Angaben zu ${esc(f.title)} (${esc(f.year)})</summary><p>${esc(f.facts)}</p>${refs(f.refs)}</details></div>`).join('')}</div><div class="comparison-task">${c?taskPanel(c.id):`<p>Für diese frei gewählte Paarung gibt es keine redigierte Vergleichsaufgabe. Beide Filme und dein Notizbuch stehen dir zur Verfügung.</p>${freeNotebook(freeKey)}`}</div>`,'compare-dialog')}
let montageRunning=false,montageIndex=0;
function montage(){return `<section class="room montage-room">${roomHeading('02 / DAS SCHNITTLABOR','Vier Momente.<em>Deine Montage.</em>','Untersuche die Verbindung zwischen der Buchseite bei 45:00 und Heidis Stadtblick bei 53:20. Beide Aufnahmen lassen sich hier direkt umstellen.')}<div class="montage-layout"><div><div class="montage-screen"><video id="montage-player" controls playsinline preload="none" poster="media/montage/alp.jpg" aria-label="Deine Montage aus Heidi 2015"></video><span id="montage-label">Deine Reihenfolge wartet.</span></div><div class="playback-tools"><button class="solid" data-action="play-montage">▶ Montage abspielen</button><button data-action="stop-montage">Stopp</button><label>Dauer pro Ausschnitt <output id="duration-output">${state.duration}</output> s<input id="segment-duration" type="range" min="2" max="8" step="1" value="${state.duration}"></label><label><input id="montage-mute" type="checkbox" ${state.muted?'checked':''}> Ohne Ton</label></div><div id="montage-strip" class="montage-strip"></div><div class="montage-foot"><button class="text-button" data-action="reverse-montage">Reihenfolge umkehren ↔</button><button class="text-button" data-action="reset-montage">Nach Zeitcode ordnen</button><details class="quiet"><summary>Woher kommen die Bilder?</summary><p>Vier achtsekündige Ausschnitte aus deiner bereitgestellten Fassung von Heidi (2015), Alain Gsponer. Die Reihenfolge hier ist dein Experiment. Die Zeitcodes beziehen sich auf diese Datei; die Bildkarten zeigen jeweils den Beginn.</p>${refs(['gsponer'])}</details></div></div><aside class="experiment-side">${taskPanel('montage')}</aside></div></section>`}
function renderStrip(){$('#montage-strip').innerHTML=state.order.map((id,i)=>{const s=E.segments.find(x=>x.id===id);return `<article class="cut-card" draggable="true" data-segment="${id}"><div class="cut-image"><img src="media/montage/${id}.jpg" alt="${esc(s.name)}"><span>${i+1}</span></div><b>${esc(s.name)}</b><small>Original ${s.start} · Auswahl ${state.duration} s</small><div><button data-move="${id}" data-delta="-1" ${i===0?'disabled':''} aria-label="${esc(s.name)} nach links">←</button><button data-move="${id}" data-delta="1" ${i===state.order.length-1?'disabled':''} aria-label="${esc(s.name)} nach rechts">→</button></div></article>`}).join('')}
function stopMontage(){montageRunning=false;const v=$('#montage-player');if(v){v.pause();v.ontimeupdate=null;v.onended=null}$('#montage-label')?.classList.remove('playing')}
async function playSegment(){const v=$('#montage-player');if(!v||!montageRunning)return;if(montageIndex>=state.order.length){stopMontage();$('#montage-label').textContent='Montage ist zu Ende. Vergleiche jetzt die umgekehrte Folge von Buchseite und Stadtblick.';return}const id=state.order[montageIndex],s=E.segments.find(s=>s.id===id);v.src='media/montage/'+id+'.mp4';v.muted=state.muted;$('#montage-label').textContent=`${montageIndex+1} / 4 · ${s.name}`;$('#montage-label').classList.add('playing');let advancing=false;const advance=()=>{if(!montageRunning||advancing)return;advancing=true;montageIndex++;playSegment()};v.ontimeupdate=()=>{if(v.currentTime>=state.duration)advance()};v.onended=advance;try{await v.play()}catch{if(montageRunning)toast('Zum Starten bitte die Wiedergabetaste im Video drücken.')}}
const traceImages=['buch-alp','buch-klara','1937','1952','1974','2015','2022','2025'];
function traces(){return `<section class="room trace-room">${roomHeading('03 / BILDSPUREN','Ein Bild.<em>Mehr als eine Lesart.</em>','Jedes Bild hat eine eigene Untersuchung. Die jeweilige Aufgabe benennt das Detail, das du markieren und deuten sollst.')}<div class="image-rail">${traceImages.map(id=>`<button data-trace-image="${id}" class="${state.image===id?'active':''}" aria-pressed="${state.image===id}" aria-label="${esc(imageFor(id).caption)}">${photo(id)}</button>`).join('')}</div><div class="trace-layout"><div><div id="trace-canvas" class="trace-canvas">${photo(state.image)}<div id="trace-marks"></div></div>${credit(state.image)}<details class="quiet"><summary>Markierung mit der Tastatur setzen</summary><label>Waagrecht <input id="mark-x" type="range" min="0" max="100" value="50"></label><label>Senkrecht <input id="mark-y" type="range" min="0" max="100" value="50"></label><button data-action="position-mark">Stelle markieren</button></details></div><aside><p id="mark-position" class="small">Die markierte Bildstelle wird mit deiner Antwort gespeichert.</p>${taskPanel('bild-'+state.image)}<div id="mark-list" class="mark-list"></div></aside></div></section>`}
function renderMarks(){const list=state.marks.filter(m=>m.image===state.image);$('#trace-marks').innerHTML=list.map((m,i)=>`<button class="pin" style="left:${m.x}%;top:${m.y}%" data-mark="${esc(m.id)}" aria-label="Spur ${i+1}: ${esc(m.text)}">${i+1}</button>`).join('')+(state.pending?`<span class="pin pending" style="left:${state.pending.x}%;top:${state.pending.y}%">＋</span>`:'');$('#mark-list').innerHTML=list.map((m,i)=>`<button data-mark="${esc(m.id)}"><span>${i+1}</span>${esc(m.text)}</button>`).join('')}
function setMark(x,y){state.pending={x:Math.max(0,Math.min(100,x)),y:Math.max(0,Math.min(100,y))};$('#mark-position').textContent='Stelle gewählt. Deine Beobachtung wird mit diesem Punkt gespeichert.';renderMarks();$('#draft-bild-'+state.image).focus()}
function timeTravel(){return `<section class="room time-room">${roomHeading('04 / ZEITREISE','Die Zeit ändert sich.<em>Heidi auch.</em>','Ziehe durch die Jahre. Öffne die Filme einer Zeit – und springe zu einer anderen.')}<div class="time-controls"><label for="time-range">Jahr entdecken <output id="time-year"></output></label><input id="time-range" type="range" min="0" max="${eras.length-1}" value="${state.yearIndex}" step="1"><div class="era-buttons">${eras.map((e,i)=>`<button data-era="${i}" class="${i===state.yearIndex?'active':''}">${e.year}</button>`).join('')}</div></div><div id="era-stage"></div></section>`}
function renderEra(){const e=eras[state.yearIndex];$('#time-year').textContent=e.year;$('#time-range').value=state.yearIndex;document.querySelectorAll('[data-era]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.era)===state.yearIndex);b.setAttribute('aria-pressed',String(Number(b.dataset.era)===state.yearIndex))});$('#era-stage').innerHTML=`<div class="era-stage"><div class="era-art">${photo(e.image)}<span>${e.year}</span></div><div class="era-copy"><p class="eyebrow">EIN ZEITFENSTER</p><h2>${e.title}</h2><p>${e.text}</p><div class="era-films">${e.ids.map(id=>{const f=films.find(f=>f.id===id);return `<button data-film="${id}">${esc(f.year)} · ${esc(f.title)} <span>↗</span></button>`}).join('')}</div><button class="solid" data-era-compare="${state.yearIndex}">Diese Fassungen nebeneinander ↗</button><details class="quiet"><summary>Quellen dieses Zeitfensters</summary>${refs(e.refs)}${credit(e.image)}</details></div></div>`}
function route(){stopMontage();if($('#overlay').open)closeOverlay();const hash=location.hash.slice(1)||'start';const filmId=hash.startsWith('film-')?hash.slice(5):null;const aliases={wege:'start',roman:'spuren',wissen:'zeit',stationen:'spuren',quellen:'kino',schnittfassungen:'kino',recherchefaelle:'kino',angekuendigt:'kino',dokumentarfilm:'kino'};const current=filmId?'kino':aliases[hash]||hash;document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#app').innerHTML=current==='kino'?cinema():current==='labor'?montage():current==='spuren'?traces():current==='zeit'?timeTravel():home();if(current==='kino')renderFilms();if(current==='labor')renderStrip();if(current==='spuren'){state.pending=null;renderMarks()}if(current==='zeit')renderEra();dock();window.scrollTo(0,0);if(filmId)openFilm(filmId);if(hash==='quellen')openSources();if(['schnittfassungen','recherchefaelle','angekuendigt','dokumentarfilm'].includes(hash))registers()}
function saveNote(key){const text=state.drafts[draftKey(key)]?.trim();if(!text){toast('Halte zuerst eine Beobachtung oder Frage fest.');return}const id=Date.now().toString(36)+Math.random().toString(36).slice(2,6);let context=key,extra={};if(key.startsWith('film-')){const f=films.find(f=>f.id===key.slice(5));context=f.year+' · '+f.title;extra.film=f.id}if(key==='montage'){context='Meine Montage · '+state.order.map(id=>E.segments.find(s=>s.id===id).name).join(' → ');extra={order:[...state.order],duration:state.duration,muted:state.muted}}if(key.startsWith('paar-')||key.startsWith('frei-'))context='Doppelblick · '+state.pair.map(id=>{const f=films.find(f=>f.id===id);return f.year+' '+f.title}).join(' / ');if(key.startsWith('bild-')){if(!state.pending){toast('Wähle zuerst eine Stelle im Bild.');return}context=imageFor(state.image).caption;const mark={id,image:state.image,text,...state.pending};state.marks.push(mark);extra.mark=mark;state.pending=null;renderMarks()}
const task=HeidiCases[key];state.notes.unshift({id,text,context,taskId:task?.id,question:task?.question,created:new Date().toISOString(),...extra});persist();dock();toast('Antwort und konkrete Frage im Entdeckungsbuch gespeichert.')}
function feedbackHTML(result){return `<h4>${esc(result.title)}</h4><ul>${result.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${result.note?`<small>${esc(result.note)}</small>`:''}`}
function notebook(){overlay('Dein Entdeckungsbuch',`<div class="notebook-intro"><p>${state.notes.length} gespeicherte Antworten und Notizen mit ihrem jeweiligen Gegenstand.</p><button class="solid" data-action="export">Als Text herunterladen ↓</button></div><div class="notes-grid">${state.notes.map(n=>`<article class="note"><p class="eyebrow">${esc(n.context)}</p>${n.question?`<p class="note-question">${esc(n.question)}</p>`:''}<p class="note-text">${esc(n.text)}</p>${n.order?`<button data-restore="${esc(n.id)}">Montage wieder öffnen ↗</button>`:''}<button class="text-button" data-delete-note="${esc(n.id)}">Diese Notiz entfernen</button></article>`).join('')||'<div class="empty"><h3>Noch ein unbeschriebenes Blatt.</h3><p>Deine ersten Filmbeobachtungen, Bildmarkierungen und Montagen finden hier Platz.</p></div>'}</div>`,'notebook-dialog')}

function openSources(){overlay('Quellen & Hintergründe',`<div class="library-intro"><h3>Texte, Filme und Bildnachweise.</h3><p>Die Aufgaben benennen ihre jeweilige Grundlage. Hier stehen die vollständigen Dokumente und Katalognachweise.</p></div><div class="library-grid">${[['Die bereitgestellten Dokumente',['klimek','takahata','walther','dossier']],['Roman, Religion & Körper',['stetter','leskau','klimek']],['Übersetzung & Weltreise',['osullivan','bando','tomkowiak']],['Archiv & Erinnerung',['unesco','archiv','tourism']]].map(([title,keys])=>`<details class="reveal"><summary>${title}</summary>${refs(keys)}</details>`).join('')}</div><details class="reveal"><summary>Alle Film- und Produktionsquellen</summary>${refs(Object.keys(sources))}</details><details class="reveal"><summary>Bildnachweise</summary>${images.map(i=>`<p><a href="${esc(i.source)}" target="_blank" rel="noopener">${esc(i.caption)}</a><br><small>${esc(i.credit)}</small></p>`).join('')}<p>Die vier Montagebilder und achtsekündigen Ausschnitte stammen aus der bereitgestellten Datei Heidi 2015.mp4 (03:00, 15:00, 45:00, 53:20).</p></details><div class="download-row"><a href="Filmografie_Heidi.json" download>Filmografie ↓</a><a href="Clipnachweise_Heidi.json" download>Videoquellen ↓</a><a href="Arbeitsheft_Heidi.md">Ausführliches Arbeitsheft ↗</a></div>`)}
function coverage(){const missing=films.filter(f=>!f.video&&!f.clip);overlay('Offene Fundstellen',`<p>31 von 35 Archiveinträgen enthalten ein Video. Darunter ist Karpis Trailerexperiment, kein Langfilm. Der vollständige Realfilm von 2015 ist zusätzlich direkt verfügbar.</p>${missing.map(f=>`<details class="reveal"><summary>${esc(f.year+' · '+f.title)}</summary><p>${esc(f.clipGap)}</p>${refs(f.refs)}</details>`).join('')}<p class="small">Die 13 Schnittfassungen sind nicht durch ausgabenspezifische Clips belegt. Externe Anbieter können ihre Videos ändern oder regional beschränken.</p>`)}
function registers(){overlay('Die Ränder des Archivs',[[filmVariants,'Schnittfassungen & Ausgaben'],[filmResearch,'Offene Zuordnungen'],[filmUpcoming,'Angekündigte Produktionen'],[filmDocumentaries,'Dokumentarische Blicke']].map(([rows,title])=>`<details class="reveal"><summary>${title} · ${rows.length}</summary>${rows.map(r=>`<article class="register-entry"><h3>${esc(r[0]+' · '+r[1])}</h3><p>${esc(r[2])}</p><a href="${esc(r[3])}" target="_blank" rel="noopener">Nachweis ↗</a></article>`).join('')}</details>`).join(''))}
function workshops(){overlay('Einzeln redigierte Vergleiche & Quellenarbeit',`<div class="workshop-grid">${Object.values(HeidiCases).filter(c=>c.pair).map(c=>`<article class="register-entry"><h3>${esc(c.title)}</h3><p>${esc(c.where)}</p><button class="solid" data-case-pair="${c.id}">Diesen Vergleich öffnen ↗</button></article>`).join('')}</div><div class="source-workshop">${taskPanel('quelle-walther')}</div>`)}
function exportNotes(){const text='HEIDI · MEIN ENTDECKUNGSBUCH\n\n'+state.notes.map(n=>n.context+'\n'+(n.question?'Frage: '+n.question+'\n':'')+n.text+(n.duration?'\nMontage: '+n.duration+' Sekunden je Ausschnitt; '+(n.muted?'ohne Ton':'mit Ton'):'')).join('\n\n---\n\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='Heidi_Meine_Entdeckungen.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b){if(b.dataset.casePair){state.pair=[...HeidiCases[b.dataset.casePair].pair];dock();compare();return}if(b.dataset.seek){const v=$('#overlay video');if(v){const time=Number(b.dataset.seek);const jump=()=>{v.currentTime=time;v.play().catch(()=>toast('Bitte die Wiedergabetaste im Film drücken.'))};if(v.readyState>=1)jump();else{v.addEventListener('loadedmetadata',jump,{once:true});v.load()}}return}if(b.dataset.film){openFilm(b.dataset.film,b.dataset.full==='true');return}if(b.dataset.play){loadClip(b.dataset.play,b.dataset.target);return}if(b.dataset.pair){state.pair=E.togglePair(state.pair,b.dataset.pair);if($('#overlay').open)closeOverlay();if($('#film-grid'))renderFilms();dock();toast(state.pair.length===2?'Zwei Fassungen ausgewählt. Dein Doppelblick ist bereit.':'Fassung für den Doppelblick ausgewählt.');return}if(b.dataset.kind){state.kind=b.dataset.kind;document.querySelectorAll('[data-kind]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderFilms();return}if(b.dataset.save){saveNote(b.dataset.save);return}if(b.dataset.reflect){$('#reflection-'+b.dataset.reflect).innerHTML=feedbackHTML(HeidiCaseFeedback.evaluate(b.dataset.reflect,state.drafts[draftKey(b.dataset.reflect)]||''));return}if(b.dataset.move){stopMontage();state.order=E.moveItem(state.order,b.dataset.move,Number(b.dataset.delta));renderStrip();return}if(b.dataset.traceImage){state.image=b.dataset.traceImage;route();return}if(b.dataset.mark){const m=state.marks.find(m=>m.id===b.dataset.mark);if(m){$('#mark-position').textContent=m.text}return}if(b.dataset.era!==undefined){state.yearIndex=Number(b.dataset.era);renderEra();return}if(b.dataset.eraCompare!==undefined){state.pair=[...eras[Number(b.dataset.eraCompare)].ids];dock();compare();return}if(b.dataset.restore){const n=state.notes.find(n=>n.id===b.dataset.restore);state.order=[...n.order];state.duration=n.duration;state.muted=n.muted;closeOverlay();location.hash='labor';route();return}if(b.dataset.deleteNote){state.notes=state.notes.filter(n=>n.id!==b.dataset.deleteNote);state.marks=state.marks.filter(m=>m.id!==b.dataset.deleteNote);persist();dock();notebook();return}
const a=b.dataset.action;if(a==='close')closeOverlay();if(a==='notebook')notebook();if(a==='sources')openSources();if(a==='workshops')workshops();if(a==='coverage')coverage();if(a==='registers')registers();if(a==='compare')compare();if(a==='clear-pair'){state.pair=[];dock();if($('#film-grid'))renderFilms()}if(a==='surprise'){const list=E.filterFilms(films,state);if(list.length)openFilm(list[Math.floor(Math.random()*list.length)].id);else toast('Keine Treffer. Setze die Filter zurück.')}if(a==='reset-filters'){state.query='';state.kind='Alle';state.until=2025;state.videoOnly=false;route()}if(a==='play-montage'){stopMontage();montageRunning=true;montageIndex=0;playSegment()}if(a==='stop-montage')stopMontage();if(a==='reverse-montage'){stopMontage();state.order.reverse();renderStrip()}if(a==='reset-montage'){stopMontage();state.order=E.segments.map(s=>s.id);renderStrip()}if(a==='position-mark')setMark(Number($('#mark-x').value),Number($('#mark-y').value));if(a==='export')exportNotes()}
if(e.target.matches('#trace-canvas>img')){const r=e.target.getBoundingClientRect();setMark((e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100)}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.draft){state.drafts[draftKey(t.dataset.draft)]=t.value;persist();const r=$('#reflection-'+t.dataset.draft);if(r?.textContent)r.textContent='Dein Gedanke hat sich verändert. Du kannst erneut eine Rückmeldung holen.'}if(t.id==='film-search'){state.query=t.value;renderFilms()}if(t.id==='year-limit'){state.until=Number(t.value);$('#year-output').textContent=t.value;renderFilms()}if(t.id==='video-only'){state.videoOnly=t.checked;renderFilms()}if(t.id==='segment-duration'){stopMontage();state.duration=Number(t.value);$('#duration-output').textContent=t.value;renderStrip()}if(t.id==='montage-mute'){state.muted=t.checked;$('#montage-player').muted=t.checked}if(t.id==='time-range'){state.yearIndex=Number(t.value);renderEra()}});
let dragged=null;document.addEventListener('dragstart',e=>{const c=e.target.closest('[data-segment]');if(c){dragged=c.dataset.segment;e.dataTransfer.setData('text/plain',dragged)}});document.addEventListener('dragover',e=>{if(e.target.closest('[data-segment]'))e.preventDefault()});document.addEventListener('drop',e=>{const c=e.target.closest('[data-segment]');if(c&&dragged&&c.dataset.segment!==dragged){e.preventDefault();stopMontage();const order=[...state.order],from=order.indexOf(dragged),to=order.indexOf(c.dataset.segment);order.splice(from,1);order.splice(to,0,dragged);state.order=order;renderStrip()}dragged=null});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeOverlay()});$('#overlay').addEventListener('close',()=>{if(!$('#overlay').open)$('#overlay-body').innerHTML=''});window.addEventListener('hashchange',route);route();
